onClick:
{{
  // 1. Explicitly run the API to get the latest user list
  GetAllUsers.run(() => {

    // 2. Once the API succeeds, we can safely access the data
    const allUsers = GetAllUsers.data;

    // 3. Match the input email
    const foundUser = allUsers.find(u => u.email === inp_email.text);

    if (foundUser) {
      // 4. Store identity and navigate
      storeValue('userId', foundUser.id);
      storeValue('userName', foundUser.firstName);

      showAlert('Login successful. Welcome, ' + foundUser.firstName, 'success');
      navigateTo('Dashboard');
    } else {
      showAlert('Login failed: Email not found.', 'error');
    }

  }, () => {
    // 6. Handle case where the API itself fails (e.g. Backend is down)
    showAlert('System Error: Could not connect to the server.', 'error');
  });
}}
